[CmdletBinding()]
param([string]$RepositoryRoot = '')
if ([string]::IsNullOrWhiteSpace($RepositoryRoot)) { $RepositoryRoot = Split-Path -Parent (Split-Path -Parent $PSScriptRoot) }
$ErrorActionPreference='Stop';$ops=Join-Path (Resolve-Path -LiteralPath $RepositoryRoot).Path 'docs/etc/operations';$all=@(Import-Csv (Join-Path $ops 'm0-t276-s5-unique-call-disposition-ledger.tsv') -Delimiter "`t");$l=@(Import-Csv (Join-Path $ops 'm0-t277-effective-source-correlation-ledger.tsv') -Delimiter "`t");$iface=@(Import-Csv (Join-Path $ops 'm0-t277-interface-recovery-ledger.tsv') -Delimiter "`t")
if($all.Count -ne 3697 -or $l.Count -ne 3697){throw "Expected 3697 source correlations; all=$($all.Count), effective=$($l.Count)."};if(Compare-Object ($all.disposition_id|Sort-Object) ($l.disposition_id|Sort-Object)){throw 'Effective ledger does not cover exact original correlation IDs.'};if(($l.disposition_id|Sort-Object -Unique).Count -ne 3697){throw 'Effective correlation IDs are not unique.'};if(@($l|? effective_state -eq 'reviewed-future-host').Count -ne 325){throw 'Expected 325 reviewed future-host rows.'};if(@($l|? effective_state -eq 'non-runtime-or-profile-excluded').Count -ne 3372){throw 'Expected 3372 excluded/profile rows.'};if(@($iface|? row_kind -eq 'lexical-declaration-candidate').Count -ne 4803){throw 'Expected 4803 retained lexical-only declaration rows.'};if(@($l|? {$_.effective_state -eq 'reviewed-future-host' -and ($_.limitation -ne 'source-form reviewed; implementation not enabled' -or [string]::IsNullOrWhiteSpace($_.family))}).Count){throw 'Reviewed rows must remain implementation-disabled and family-linked.'};Write-Host 'T277 S7 effective source-correlation reconciliation passed: correlations=3697; reviewed=325; excluded=3372; lexical-only=4803.'
